def split_csv(line):
    if not line:
        return ['']

    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i == len(line):
                            fields.append(''.join(field))
                            break
                        elif line[i] == ',':
                            fields.append(''.join(field))
                            i += 1
                            break
                        else:
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < len(line):
                i += 1

    return fields

